/* REPRODUCED:RUN:SIGNAL MACHINE:mips OPTIONS: */

#include <stdarg.h>

void abort(void);
void exit(int);

typedef struct {
  int A;
} T;

T f(int x, ...) {
  va_list ap;
  T       X;
  va_start(ap, x);
  X = va_arg(ap, T);
  if (X.A != 10)
    abort();
  X = va_arg(ap, T);
  if (X.A != 20)
    abort();
  va_end(ap);
  return X;
}

int main(void) {
  T   X, Y;
  int i;
  X.A = 10;
  Y.A = 20;
  f(2, X, Y);
  exit(0);
}


